import{_ as o,o as n,c as t,ai as a}from"./chunks/framework.C_v2XVcg.js";const f=JSON.parse('{"title":"An Introduction","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"docs/handbook/introduction.md","filePath":"docs/handbook/introduction.md"}'),i={name:"docs/handbook/introduction.md"};function s(l,e,d,r,h,c){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="an-introduction" tabindex="-1">An Introduction <a class="header-anchor" href="#an-introduction" aria-label="Permalink to “An Introduction”">​</a></h1><h2 id="the-name" tabindex="-1">The Name <a class="header-anchor" href="#the-name" aria-label="Permalink to “The Name”">​</a></h2><p>Solus is a latin word meaning alone or by oneself. solus is entirely developed by me and all of its choices reflect my own opinions on what is and isn’t good in other languages, but also what I feel is feasible for me as a single individual. The recommended file extension for solus is .solu due to it being the icon’s name, but .solus is also acceptable.</p><h2 id="why-alone" tabindex="-1">Why Alone? <a class="header-anchor" href="#why-alone" aria-label="Permalink to “Why Alone?”">​</a></h2><p>If you do want to help with solus, you can do so by either sifting through the code and finding bugs, or by writing code yourself in the language and finding edge cases I may have missed. I hope that by the 1.0 release of this language it’ll be something I can seriously be proud to show off, so I’m not really open to working with other people on it directly. Plus, the codebase is written in plain C and not exactly beginner friendly C either, it would take a lot of effort to teach other people to work around my code in ways that I would be satisfied with. And plus, the name would be really fucking dumb if I did that.</p>',5)])])}const m=o(i,[["render",s]]);export{f as __pageData,m as default};
